import{_ as l,a0 as p,w as o,s as d,ao as r,I as t,x as e,a1 as i,A as n}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const x=JSON.parse('{"title":"我如何使用現場 USB 設備恢復我的 Linux 系統 | LCTT x X-CMD","titleTemplate":false,"description":"我如何使用現場 USB 設備恢復我的 Linux 系統 | LCTT (202209) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"我如何使用現場 USB 設備恢復我的 Linux 系統 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"我如何使用現場 USB 設備恢復我的 Linux 系統 | LCTT (202209) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"202209/20220912 How I recovered my Linux system using a Live USB device","title":"我如何使用現場 USB 設備恢復我的 Linux 系統","tag":"202209","desc":""},"relativePath":"202209/20220912 How I recovered my Linux system using a Live USB device.md","filePath":"[post].md"}'),c={name:"202209/20220912 How I recovered my Linux system using a Live USB device.md"};function h(u,s,g,b,m,k){const a=p("Link");return o(),d("div",null,[s[15]||(s[15]=r(`<h1 id="我如何使用現場-usb-設備恢復我的-linux-系統" tabindex="-1">我如何使用現場 USB 設備恢復我的 Linux 系統 <a class="header-anchor" href="#我如何使用現場-usb-設備恢復我的-linux-系統" aria-label="Permalink to “我如何使用現場 USB 設備恢復我的 Linux 系統”">​</a></h1><p><img src="https://img.linux.net.cn/data/attachment/album/202209/28/121226rh7vq7qhwhqzh76m.jpg" alt=""></p><blockquote><p>Fedora 現場 USB 發行版為引導和進入恢復模式提供了有效的解決方案。</p></blockquote><p>我的家庭實驗室裏有十幾台物理計算機以及更多的虛擬機。這些系統中的大多數是我用來進行測試和實驗的。我經常寫使用自動化來簡化系統管理任務的文章。我還在多個地方寫過，我從自己的錯誤中學到的東西比幾乎任何其他方式都多。</p><p>在過去的幾周裏，我學到了很多東西。</p><p>我給自己製造了一個大麻煩。作為多年的系統管理員，我寫了數百篇關於 Linux 的文章和五本書，我應該對 Linux 更瞭解。話又説回來，我們都會犯錯，這是一個重要的教訓：你永遠不會因為有經驗而不犯錯。</p><p>我不打算討論我的錯誤的細節。告訴你這是一個錯誤就足夠了，在我做之前我應該多考慮一下我在做什麼。此外，細節並不是重點。經驗不能讓你免於犯下的每一個錯誤，但它可以幫助你恢復。這就是本文要討論的內容：使用現場 USB 發行版啓動並進入恢復模式。</p><h3 id="問題" tabindex="-1">問題 <a class="header-anchor" href="#問題" aria-label="Permalink to “問題”">​</a></h3><p>首先，我製造了問題，這本質上是 <code>/etc/default/grub</code> 文件的錯誤配置。接下來，我使用 Ansible 將錯誤配置的文件分發到我所有的物理計算機並運行 <code>grub2-mkconfig</code>。全部 12 個。這真的，真的很快。</p><p>除了兩台之外，所有的都無法啓動。它們在 Linux 啓動的早期階段崩潰，出現各種無法定位 <code>/root</code> 文件系統的錯誤。</p><p>我可以使用 root 密碼進入“維護”模式，但是如果沒有掛載 <code>/root</code>，即使是最簡單的工具也無法訪問。直接引導到恢復內核也不起作用。系統真的被破壞了。</p><h3 id="fedora-恢復模式" tabindex="-1">Fedora 恢復模式 <a class="header-anchor" href="#fedora-恢復模式" aria-label="Permalink to “Fedora 恢復模式”">​</a></h3><p>解決此問題的唯一方法是找到進入恢復模式的方法。當一切都失敗時，Fedora 提供了一個非常酷的工具：用於安裝 Fedora 新實例的<ruby>現場 USB<rt>Live USB</rt></ruby> 驅動器。</p><p>將 BIOS 設置為從現場 USB 設備啓動後，我啓動到 Fedora 36 Xfce 的<ruby>現場<rt>live</rt></ruby>用户桌面。我在桌面上打開了兩個相鄰的終端會話，並在兩者中都切換到了 root 權限。</p><p>我在其中一個運行了 <code>lsblk</code> 以供參考。我使用該結果來識別 <code>/</code> 根分區以及 <code>boot</code> 和 <code>efi</code> 分區。我使用了我的一台虛擬機，如下所示。在這種情況下沒有 <code>efi</code> 分區，因為此 VM 不使用 UEFI。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span># lsblk</span></span>
<span class="line"><span>NAME          MAJ:MIN RM  SIZE RO TYPE MOUNTPOINTS</span></span>
<span class="line"><span>loop0           7:0    0  1.5G  1 loop</span></span>
<span class="line"><span>loop1           7:1    0    6G  1 loop</span></span>
<span class="line"><span>├─live-rw     253:0    0    6G  0 dm   /</span></span>
<span class="line"><span>└─live-base   253:1    0    6G  1 dm   </span></span>
<span class="line"><span>loop2           7:2    0   32G  0 loop</span></span>
<span class="line"><span>└─live-rw     253:0    0    6G  0 dm   /</span></span>
<span class="line"><span>sda             8:0    0  120G  0 disk</span></span>
<span class="line"><span>├─sda1          8:1    0    1G  0 part</span></span>
<span class="line"><span>└─sda2          8:2    0  119G  0 part</span></span>
<span class="line"><span>  ├─vg01-swap 253:2    0    4G  0 lvm  </span></span>
<span class="line"><span>  ├─vg01-tmp  253:3    0   10G  0 lvm  </span></span>
<span class="line"><span>  ├─vg01-var  253:4    0   20G  0 lvm  </span></span>
<span class="line"><span>  ├─vg01-home 253:5    0    5G  0 lvm  </span></span>
<span class="line"><span>  ├─vg01-usr  253:6    0   20G  0 lvm  </span></span>
<span class="line"><span>  └─vg01-root 253:7    0    5G  0 lvm  </span></span>
<span class="line"><span>sr0            11:0    1  1.6G  0 rom  /run/initramfs/live</span></span>
<span class="line"><span>zram0         252:0    0    8G  0 disk [SWAP]</span></span></code></pre></div><p><code>/dev/sda1</code> 分區很容易識別為 <code>/boot</code>，根（<code>/</code>）分區也很明顯。</p><p>在另一個終端會話中，我執行了一系列步驟來恢復我的系統。特定的卷組名稱和設備分區（例如 <code>/dev/sda1</code>）因系統而異。此處顯示的命令特定於我的情況。</p><p>目標是使用現場 USB 引導並完成啓動，然後僅在鏡像目錄中掛載必要的文件系統，並運行 <code>chroot</code> 命令在 chroot 鏡像目錄中運行 Linux。這種方法繞過損壞的 GRUB（或其他）配置文件。但是，它提供了一個完整的運行系統，其中安裝了所有原始文件系統以進行恢復，既是所需工具的來源，也是要進行更改的目標。</p><p>以下是步驟和相關命令：</p><ol><li>創建目錄 <code>/mnt/sysimage</code> 以提供 <code>chroot</code> 目錄的位置。</li><li>將根分區掛載到 <code>/mnt/sysimage</code>：<div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span># mount /dev/mapper/vg01-root /mnt/sysimage</span></span></code></pre></div></li><li>將 <code>/mnt/sysimage</code> 設為你的工作目錄：<div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span># cd /mnt/sysimage</span></span></code></pre></div></li><li>掛載 <code>/boot</code> 和 <code>/boot/efi</code> 文件系統。</li><li>掛載其他主要文件系統。此步驟不需要像 <code>/home</code> 和 <code>/tmp</code> 這樣的文件系統：<div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span># mount /dev/mapper/vg01-usr usr</span></span>
<span class="line"><span></span></span>
<span class="line"><span># mount /dev/mapper/vg01-var var</span></span></code></pre></div></li><li>綁定已掛載的重要文件系統，它們必須在已經 chroot 的系統和原始的現場系統之間共享，而後者仍然在外部運行：<div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span># mount --bind /sys sys</span></span>
<span class="line"><span></span></span>
<span class="line"><span># mount --bind /proc proc</span></span></code></pre></div></li><li>一定要最後操作 <code>/dev</code> 目錄，否則其他文件系統不能掛載：<div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span># mount --bind /dev dev</span></span></code></pre></div></li><li>chroot 到系統鏡像：<div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span># chroot /mnt/sysimage</span></span></code></pre></div></li></ol><p>系統現在已經準備好了，無論你需要做什麼，都可以把它恢復到一個工作狀態。然而，有一次我能夠在這種狀態下運行我的服務器數天，直到我能夠研究測試出真正的修復方法。我並不推薦這樣做，但在緊急情況下，當有任務需要啓動和運行時，這可能是一個選擇。</p><h3 id="解決方案" tabindex="-1">解決方案 <a class="header-anchor" href="#解決方案" aria-label="Permalink to “解決方案”">​</a></h3><p>當我讓每個系統進入恢復模式，修復就很容易了。因為我的系統現在就像成功啓動一樣工作，我只需對 <code>/etc/default/grub</code> 和 <code>/etc/fstab</code> 進行必要的更改並運行 <code>grub2-mkconfig &gt; boot/grub2/grub.cfg</code> 命令。我使用 <code>exit</code> 命令退出 chroot 環境，然後重啓主機。</p><p>當然，我無法自動從我的意外事故中恢復過來。我必須在每台主機上手動執行整個過程，這是使用自動化快速和容易地傳播我自己的錯誤的一點報應。</p><h3 id="得到教訓" tabindex="-1">得到教訓 <a class="header-anchor" href="#得到教訓" aria-label="Permalink to “得到教訓”">​</a></h3><p>儘管它們很有用，我曾經討厭在我的一些系統管理員工作中舉行的“經驗教訓”會議，但看來我確實需要提醒自己一些事情。因此，這裏是我從這場自作自受的慘敗中獲得的“教訓”。</p><p>首先，無法引導的十個系統使用了不同的卷組命名方案，而我的新 GRUB 配置沒有考慮到這一點。我只是忽略了它們可能不同的事實。</p><ul><li>徹底考慮清楚。</li><li>並非所有系統都相同。</li><li>測試一切。</li><li>驗證一切。</li><li>永遠不要做假設。</li></ul><p>現在一切正常。希望我也聰明一點。</p><hr>`,31)),t("p",null,[s[1]||(s[1]=e("via: ",-1)),i(a,{href:"https://opensource.com/article/22/9/recover-linux-system-live-usb"},{default:n(()=>[...s[0]||(s[0]=[e("https://opensource.com/article/22/9/recover-linux-system-live-usb",-1)])]),_:1})]),t("p",null,[s[6]||(s[6]=e("作者：",-1)),i(a,{href:"https://opensource.com/users/dboth"},{default:n(()=>[...s[2]||(s[2]=[e("David Both",-1)])]),_:1}),s[7]||(s[7]=e(" 選題：",-1)),i(a,{href:"https://github.com/lkxed"},{default:n(()=>[...s[3]||(s[3]=[e("lkxed",-1)])]),_:1}),s[8]||(s[8]=e(" 譯者：",-1)),i(a,{href:"https://github.com/geekpi"},{default:n(()=>[...s[4]||(s[4]=[e("geekpi",-1)])]),_:1}),s[9]||(s[9]=e(" 校對：",-1)),i(a,{href:"https://github.com/wxy"},{default:n(()=>[...s[5]||(s[5]=[e("wxy",-1)])]),_:1})]),t("p",null,[s[12]||(s[12]=e("本文由 ",-1)),i(a,{href:"https://github.com/LCTT/TranslateProject"},{default:n(()=>[...s[10]||(s[10]=[e("LCTT",-1)])]),_:1}),s[13]||(s[13]=e(" 原創編譯，",-1)),i(a,{href:"https://linux.cn/"},{default:n(()=>[...s[11]||(s[11]=[e("Linux中國",-1)])]),_:1}),s[14]||(s[14]=e(" 榮譽推出",-1))])])}const y=l(c,[["render",h]]);export{x as __pageData,y as default};
